<script>(()=>{const form=document.getElementById('ownership-form');const bikes={{ Illuminate\Support\Js::from($bikeSearchOptions) }};const customers={{ Illuminate\Support\Js::from($customerSearchOptions) }};const bikeSearch=form.querySelector('[data-bike-search]');const bikeId=form.querySelector('[data-bike-id]');const ownerSearch=form.querySelector('[data-owner-search]');const ownerId=form.querySelector('[data-owner-id]');const syncBike=()=>{const match=bikes.find(bike=>bike.label.toLowerCase()===bikeSearch.value.trim().toLowerCase());bikeId.value=match?.id||'';bikeSearch.setCustomValidity(bikeSearch.value&&!match?'Choose a bike from the search results.':'');form.querySelector('[data-current-owner]').textContent=match?.owner||'Select a bike';form.querySelector('[data-current-phone]').textContent=match?.phone||'';form.querySelector('[data-current-model]').textContent=match?.model||'—';};const syncOwner=()=>{const match=customers.find(customer=>customer.label.toLowerCase()===ownerSearch.value.trim().toLowerCase());ownerId.value=match?.id||'';ownerSearch.setCustomValidity(ownerSearch.value&&!match?'Choose a customer from the search results.':'');};bikeSearch.addEventListener('input',syncBike);ownerSearch.addEventListener('input',syncOwner);form.addEventListener('submit',()=>{syncBike();syncOwner();});syncBike();})();</script></div></x-layouts::app>
